class Solution {
    public boolean checkStrings(String s1,String s2){
        int[][] count=new int[2][26];
        for(int i=0;i<s1.length();i++){
            count[i%2][s1.charAt(i)-'a']++;
            count[i%2][s2.charAt(i)-'a']--;
        }
        for(int[] row:count)for(int value:row)if(value!=0)return false;
        return true;
    }
}

code.kotlin:
class Solution {
    fun checkStrings(s1:String,s2:String):Boolean{
        val count=Array(2){
            IntArray(26)
        };
        for(i in s1.indices){
            count[i%2][s1[i]-'a']++;
            count[i%2][s2[i]-'a']--
        };
        return count.all{
            row->row.all{
                it==0
            }
        }
    }
}

